{
  "id": 50,
  "knowledge": "Resource Utilization Classification",
  "description": "Categorizes distribution hubs based on their Resource Utilization Ratio (RUR) values",
  "definition": "High Utilization (RUR > 5) indicates potentially overloaded hubs that may need resource expansion; Moderate Utilization (2 \u2264 RUR \u2264 5) represents optimal resource usage balance; Low Utilization (RUR < 2) indicates underutilized hubs with potential efficiency gains through resource reallocation"
}

{
  "id": 53,
  "knowledge": "available storage percentage",
  "description": "Calculates what proportion of total storage capacity is currently available",
  "definition": "The percentage calculated by dividing available storage (storeavailm3) by total storage capacity (storecapm3) and multiplying by 100"
}

{
  "id": 6,
  "knowledge": "resourceallocstate",
  "description": "Illustrates the adequacy of resource distribution",
  "definition": "Sufficient means resources meet current operational needs, Limited indicates resources are stretched and prioritization is necessary, and Critical represents severe shortages requiring immediate supplementation"
}

{
  "id": 11,
  "knowledge": "Operational Efficiency Index (OEI)",
  "description": "Quantifies operational efficiency based on resource allocation and supply flow",
  "definition": "OEI = \\frac{deliverysuccessrate}{100} \\times \\left(1 - \\frac{avgdeliveryhours}{24}\\right) \\times \\left(1 + \\frac{distributionpoints}{10}\\right)"
}

{
  "id": 22,
  "knowledge": "Resource Optimization Opportunity",
  "description": "Identifies situations where resource allocation could be optimized",
  "definition": "A scenario where hubutilpct < 30 while simultaneously having distributionpoints > 20, suggesting potential for redistribution of resources to maximize efficiency"
}

{
  "id": 15,
  "knowledge": "Logistics Performance Metric (LPM)",
  "description": "Measures the overall performance of logistics operations",
  "definition": "LPM = \\frac{totaldeliverytons}{hubcaptons} \\times deliverysuccessrate \\times \\left(1 - \\frac{vehiclebreakrate}{100}\\right) \\times 100"
}

{
  "id": 30,
  "knowledge": "Response Time Effectiveness Ratio (RTER)",
  "description": "Measures how quickly and effectively disaster response operations are deployed",
  "definition": "RTER = \\frac{100}{estdurationdays + 1} \\times \\frac{deliverysuccessrate}{100} \\times \\left(\\frac{4 - respphase\\_numeric}{3}\\right), \\text{ where respphase\\_numeric maps Initial=1, Emergency=2, Recovery=3, Reconstruction=4, else=0, representing faster deployment relative to disaster phase}"
}

{
  "id": 51,
  "knowledge": "Environmental Impact Classification",
  "description": "Categorizes operations based on their Environmental Impact Factor (EIF) values",
  "definition": "Sustainable (EIF < 50) indicates operations with minimal environmental footprint and strong sustainability practices; Moderate Impact (50 \u2264 EIF < 100) represents operations with reasonable environmental management; High Impact (EIF \u2265 100) indicates operations with significant environmental footprint requiring mitigation strategies"
}

{
  "id": 52,
  "knowledge": "Community Resilience Classification",
  "description": "Categorizes operations based on their community engagement and resilience-building effectiveness",
  "definition": "Operations satisfying criteria from Community Resilience Builder are classified as Community Resilience Builder; operations meeting criteria from Community Resilience Opportunity are classified as Community Resilience Opportunity; all other operations are classified as Standard Operation"
}

{
  "id": 49,
  "knowledge": "Rapid Response Success Model",
  "description": "Identifies exemplary rapid deployment operations",
  "definition": "Operations where RTER > 20 AND OEI > 2.5 AND deliverysuccessrate > 85, representing highly effective and rapidly deployed response operations that can serve as models for future disasters"
}

{
  "id": 15,
  "knowledge": "Logistics Performance Metric (LPM)",
  "description": "Measures the overall performance of logistics operations",
  "definition": "LPM = \\frac{totaldeliverytons}{hubcaptons} \\times deliverysuccessrate \\times \\left(1 - \\frac{vehiclebreakrate}{100}\\right) \\times 100"
}

{
  "id": 31,
  "knowledge": "Resource Distribution Equity (RDE)",
  "description": "Evaluates the fairness of resource distribution across affected areas",
  "definition": "RDE = distequityidx \\times \\left(1 + \\frac{distributionpoints}{20}\\right) \\times \\left(1 - \\frac{100 - deliverysuccessrate}{100}\\right) \\times coordeffect\\_factor, \\text{ where coordeffect\\_factor is 1.2 for High, 1.0 for Medium, 0.8 for Low coordination effectiveness level, and 0 for else}"
}

{
  "id": 13,
  "knowledge": "Personnel Effectiveness Ratio (PER)",
  "description": "Evaluates how effectively human resources are utilized in operations",
  "definition": "PER = \\frac{staffingprofile->>'personnel'->>'total'}{(personnelcostsusd / 10000)} \\times \\frac{staffingprofile->>'readiness'->>'availability_percent'}{100}"
}

{
  "id": 18,
  "knowledge": "Financial Sustainability Ratio (FSR)",
  "description": "Assesses the financial sustainability of disaster response operations",
  "definition": "FSR = \\frac{donorcommitmentsusd}{budgetallotusd} \\times \\left(1 - \\frac{fundsutilpct}{100}\\right) - \\frac{resourcegapsusd}{budgetallotusd}"
}
